"""Assemble release evidence from actual saved runs; does not invoke models or APIs."""
from pathlib import Path
import json,re,hashlib,html
ROOT=Path(__file__).resolve().parents[1]

def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()

def main():
    log=(ROOT/'build/release-final-checks.log').read_text()
    assert re.search(r'100% tests passed(?:, 0 tests failed)? out of 2',log)
    assert re.findall(r'Ran (\d+) tests',log)==['15','38']
    assert 'FAILED (' not in log
    absent=(ROOT/'build/release-model-absent-tests.log').read_text();assert 'Ran 38 tests' in absent and 'OK (skipped=1)' in absent
    assert 'AU VALIDATION SUCCEEDED' in (ROOT/'build/release-auval.log').read_text()
    live=json.loads((ROOT/'build/release-live-ai-results.json').read_text());assert len(live)==7 and all(r['response']['provider']=='openai' for r in live)
    refs=json.loads((ROOT/'ml/runs/release_acceptance/results.json').read_text());assert len(refs['valid_references'])==9 and len(refs['invalid_inputs'])==5
    video=json.loads((ROOT/'assets/demo/video-verification.json').read_text());assert video['duration_seconds']==16 and video['video_tracks']==video['audio_tracks']==1
    states={k:json.loads((ROOT/f'assets/demo/{k}.json').read_text()) for k in ['before','proposal','applied','undo']};assert states['before']==states['proposal']==states['undo']
    assert states['before']['gain']==states['applied']['gain']
    import sys
    sys.path.insert(0,str(ROOT/'ml'))
    import numpy as np
    from scipy.io import wavfile
    rate,a=wavfile.read(ROOT/'assets/demo/demo-audio.wav');n=4*rate
    assert a.shape==(n*4,) and np.isfinite(a).all() and 1e-6<float(np.abs(a).max())<1
    assert np.array_equal(a[:n],a[n:2*n]) and np.array_equal(a[:n],a[3*n:])
    installed=json.loads((ROOT/'build/release-installed-verification.json').read_text());assert all(v['exact_match'] for v in installed.values())
    human_path=ROOT/'build/release-human-checks.json'
    human=json.loads(human_path.read_text()) if human_path.exists() else {'physical_resize_drag':'pending user observation','perceptual_listening':'not measured; audition page available'}
    audit={'date':'2026-11-04','status':'technical development deliverable complete; manual experience checks explicitly separate','repository':'/Users/zhangxiai/Desktop/AI-Sound-Designer','branch':'main','origin':'https://github.com/LynneZhang-zxa/AI-Sound-Designer.git','tests':{'cpp':2,'service':15,'offline':38,'model_absent':{'run':38,'passed':37,'intentional_legacy_skip':1}},'installed':installed,'auval':'PASS','real_provider_cases':7,'provider_sources':{'captured_current_policy_real_responses_replayed_without_rebilling':3,'fresh_live_requests_in_final_continuation':4},'references':{'controlled_independent_scipy':8,'previous_real_logic_es1':1,'invalid_inputs_rejected':5,'new_logic_exports_created':0,'human_preference_claim':False},'demo':dict(video,label='staged from actual JUCE editor snapshots + renderer; not Logic screen recording',before_preview_undo_audio_identical=True),'manual':human,'known_limits':['dry single-note Match with known gate; limited synth topology','no new human listening preference/real-recording generalization claim','native resize automation failed at tool layer; geometry and hit tests passed','LLM interpretations/explanations remain reviewable, language consistency not guaranteed','callback instrumentation covers exercised C++ new calls, not system-wide allocation/lock profiling','no notarized distribution or host CPU benchmark'],'git_commit_push':False}
    evidence=['build/release-final-checks.log','build/release-model-absent-tests.log','build/release-live-ai.log','build/release-live-ai-results.json','build/release-live-ai-original-observations.log','build/release-live-ai-before-policy-fix.log','build/release-live-ai-policy-observations.log','build/release-service-tests.log','build/release-auval.log','ml/runs/release_acceptance/results.json','assets/demo/resonanca-demo.mp4','assets/demo/demo-audio.wav','assets/demo/video-verification.json']
    audit['evidence_sha256']={n:digest(ROOT/n) for n in evidence};(ROOT/'build/release-audit.json').write_text(json.dumps(audit,indent=2)+'\n')
    lines=['# Initial development deliverable — 2026-11-04','','Technical implementation, reproducible checks and demo materials are complete for the documented controlled scope. This is a development/portfolio deliverable; human preference and physical resize feel remain separately reported, not inferred from technical tests.','','| Gate | Current evidence |','|---|---|','| Canonical repository | Desktop AI-Sound-Designer; main; expected GitHub origin; no commit/push |','| AU/VST3 + renderer/test build | scripts/check-release.sh exited successfully; generated-bundle strict verification passed |','| Installed binaries | Exact SHA-256 equality with canonical build; installed signatures verified |','| Apple validation | AU VALIDATION SUCCEEDED in build/release-auval.log |','| C++ processor/editor | 2/2 CTests; state/MIDI/rates/blocks/proposals/resize bounds and hit testing |','| Service/launcher/client | 15 tests; malformed/provider failure/origin boundaries; actual pending-worker cancellation in <2s while callbacks continue |','| Offline tools | 38 tests passed |','| Model-absent source setup | 38 run: 37 passed, one explicitly skipped optional legacy browser-workbench test |','| Real OpenAI | Seven cases through actual C++ transport and shared protection/apply path; no fallback counted as AI success |','| Reference matrix | Eight independent SciPy notes + one existing Logic ES1 export; five invalid inputs rejected |','| Demo | Verified 16s, one video + one audio track, 1200×1080, actual JUCE states/audio |','| Physical mouse resizing | '+str(human['physical_resize_drag'])+' |','| Perceptual listening | '+str(human['perceptual_listening'])+' |','','## Real-provider observations and corrections','','The current prompt policy separates context/history from the latest request and gives explicit 0=sine/1=saw/2=square/3=triangle IDs. This corrected an observed previous-intent carryover. Earlier raw responses, including a wrong waveform ID, are retained; the plugin explicit-waveform guard corrected that value before Apply. Explanations remain best effort and numerical preview/measurements are authoritative. One Chinese request received an English explanation; language conformity is not claimed perfect.','','Acceptance also distinguished generic shorter (decay or release) from explicit tail shortening, and explanation-only questions from unsupported action requests. The harness originally over-constrained those cases and incorrectly added no-op questions to applied history; those test issues were corrected rather than hidden as product failures. Current-policy real responses for the first three cases were replayed through the same parameter pipeline without additional billing; four later cases used new live requests. This is seven observed cases, not seven new requests in the final invocation or a statistical success-rate benchmark. Default checks make no paid API calls.','','| Case | Actual intent | Evidence |','|---|---|---|']
    for i,row in enumerate(live):lines.append(f"| {i} | {row['prompt'].replace('|','/')} | {row['source']} |")
    lines+=['','## Reference matrix','','Same default starting patch, supplied known MIDI pitch/gate, actual loopback Match service, original source bytes retained. Scores use the v2 technical objective; they are not human similarity ratings and are not comparable across arbitrary objective versions. The eight new sources use independent SciPy oscillators/Butterworth filtering; they are controlled synthetic fixtures, not eight new Logic exports or a broad third-party recording benchmark.','','| Reference | Baseline score | Matched score |','|---|---|---|']
    for row in refs['valid_references']:lines.append(f"| {row['name']} | {row['result']['baseline']['score']} | {row['result']['matched']['score']} |")
    lines+=['','Every request retained legal parameters, preserved gain and produced waveform/spectral artifacts. Rejected: wrong extension, silence, nonfinite audio, out-of-range gate and invalid note. No preference score is invented. Higher residuals in some pluck/pad examples and the ES1 partial/tail mismatch remain known limits of the current synth/search. Listen at `ml/runs/release_acceptance/index.html`.','','## Reproduce and demonstrate','','- Build/install/start: README.md and docs/quick-start.md.','- Credential-free release checks: `bash scripts/check-release.sh`.','- Optional real-provider acceptance: `build/SynthTests --release-ai` (running configured service; paid requests).','- Reference matrix: `ml/.venv/bin/python scripts/release-acceptance.py` (refuses to overwrite its recorded run).','- Demo generation: `ml/.venv/bin/python scripts/prepare-demo.py`.','- Video inspection: `swift -module-cache-path build/swift-cache scripts/inspect-demo.swift assets/demo`.','- Evidence report only, no model/API calls: `ml/.venv/bin/python scripts/report-release.py`.','','## Delivery boundary','','The synth, editable assistant and controlled reference workflow are implemented. The CNN remains offline because equal-budget search gave 24/24 ties; full unfavorable metrics are in ml/MATCH_MODEL_RESULTS.md. No new training followed that result. Reverb/unison/stereo width/arbitrary music matching, exact external preset cloning, distribution notarization and broad host/perceptual benchmarking remain outside this initial version.','','Previous actual Logic MIDI/automation/state/AI and current Analyze/Match/Apply/Undo observations are dated in docs/verification.md and docs/initial-release.md. New C++/service tests do not masquerade as fresh mouse clicks or listening approval. Native resize geometry/input checks passed; physical dragging awaits user observation because the control tool failed that action. No destructive host termination, old-workspace edits, commits or pushes were performed.','','`build/release-audit.json` binds current evidence hashes. Build/log/run files are intentionally Git-ignored; source protocols, measured summaries, docs and staged demo assets are available for the owner to review and commit.']
    (ROOT/'docs/release-status.md').write_text('\n'.join(lines)+'\n')
    cards=[]
    for row in refs['valid_references']:
        name=row['name']
        if name=='Logic_ES1_existing':continue
        cards.append(f'<section><h2>{html.escape(name)}</h2><p>MIDI {row["known_midi_note"]}; Gate {row["gate_seconds"]*1000:g} ms. Controlled independent source.</p><p>Reference</p><audio controls src="{name}-reference.wav"></audio><p>Match</p><audio controls src="{name}-match.wav"></audio></section>')
    (ROOT/'ml/runs/release_acceptance/index.html').write_text('<!doctype html><meta charset="utf-8"><title>Release Match listening</title><style>body{font:17px system-ui;max-width:900px;margin:40px auto;background:#10151b;color:#eee}section{padding:20px;border-bottom:1px solid #456}audio{width:100%}</style><h1>Release Match listening</h1><p>Independent SciPy fixtures; held-window RMS aligned, not LUFS. Original files and technical receipts retained. No human preference judgment has been recorded.</p>'+''.join(cards))
    print('Release report and hash-bound evidence audit generated; no inference or API calls.')
if __name__=='__main__':main()
